# Same results and corrections as rev4 v3; text condensed; detailed tables and figures moved to the supplement (S24-S28, Figures S10-S15).
# ------------------------------------------------------------------ helpers used below (as in rev4 Section 4.1)
slope_rng = lambda d: (min(fold_slope[(d, m)] for m in MODELS), max(fold_slope[(d, m)] for m in MODELS))
pool_rng = lambda d: (min(pool_slope[(d, m)][0] for m in MODELS), max(pool_slope[(d, m)][0] for m in MODELS))
bss_rng = lambda d: (min(bss[(d, m)][0] for m in MODELS), max(bss[(d, m)][0] for m in MODELS))
# ------------------------------------------------------------------ abstract
holm_fmd = max(float(t10(s, 'FMD')['Holm p (6 tests)']) for s in ('household', 'village'))
k_fmd = [int(t10(s, 'FMD')['Null gains >= observed']) for s in ('household', 'village')]
def _holm(p):
    o = sorted(range(len(p)), key=lambda i: p[i]); adj = [0.0] * len(p); run = 0.0
    for k, i in enumerate(o): run = max(run, min(1.0, (len(p) - k) * p[i])); adj[i] = run
    return adj
_p100 = [float(v) for v in T10['p with first 100 permutations']]
holm100_fmd = max(a for a, s, d in zip(_holm(_p100), T10.Scheme, T10.Disease) if d == 'FMD')
perm_all_exceeded = k_fmd == [0, 0]
holm_fmd_hv = [float(t10(s, 'FMD')['Holm p (6 tests)']) for s in ('household', 'village')]
def _none(k, lab): return f'none of the {n_perm:,} {lab}' if k == 0 else f'{k} of the {n_perm:,} {lab}'
def _sig(ps): return ('both below' if max(ps) < 0.05 else 'both above' if min(ps) >= 0.05 else 'one below and one above') if len(ps) == 2 else ''
sig_txt = 'below' if holm_fmd < 0.05 else 'above'
_lib = pd.read_csv(RT / 'RT3_library_models_spatial_v1.csv').set_index('Model [feature set]')
gp = {d: float(_lib.loc['GP-kriging [E]', f'{d} ROC-AUC mean (SD)'].split(' ')[0]) for d in DIS}
gp_gap = [min(fm(d, 'FS5'), fm(d, '(a) Rank average')) - gp[d] for d in DIS] + [max(fm(d, 'FS5'), fm(d, '(a) Rank average')) - gp[d] for d in DIS]
add('para', '**Abstract:** ' + (
    'Machine-learning maps of livestock disease are usually checked with random cross-validation, which can overstate accuracy when nearby observations are similar. '
    'We evaluated such maps for household-reported contagious bovine pleuropneumonia (CBPP), foot-and-mouth disease (FMD) and lumpy skin disease (LSD) in 3,340 Ethiopian households from five survey campaigns (2012-2019), using 81 km spatial block cross-validation, nested feature sets from five environmental variables to 39 features, ExtraTrees and a 23-model ensemble, a leakage audit of neighbourhood disease rates, label-permutation controls and campaign-aware tests. '
    f'Random cross-validation gave mean ensemble ROC-AUC {min(gap_a.values()):.2f}-{max(gap_a.values()):.2f} higher than spatial validation, because almost all of its test households had training households at the same location. '
    f'Under spatial validation, the engineered features improved FMD prediction (ROC-AUC {fm("FMD", "FS1"):.3f} to {fm("FMD", "FS5"):.3f}), mainly through climate indices and coordinates; the neighbourhood rates were leakage-safe but added little once location was known. '
    + (f'The FMD gain exceeded all {n_perm:,} label permutations in both permutation designs (Holm-adjusted p = {holm_fmd:.3f}). ' if perm_all_exceeded else
       f'The FMD gain was reached by {_none(k_fmd[0], "household-level")} and {_none(k_fmd[1], "village-level")} label permutations (Holm-adjusted p ≤ {holm_fmd:.3f}). ')
    + 'CBPP and LSD showed no consistent gain. '
    f'Much of the apparent skill reflected differences between survey campaigns: within single years ROC-AUC was only {min(wy_best.values()):.2f}-{max(wy_best.values()):.2f}, and models trained on 2012-2015 did not transfer to 2018-2019. '
    'Such maps can help rank surveyed areas within one campaign for follow-up surveillance, but should not be used to compare campaigns or to forecast.'))
add('para', '**Keywords:** Spatial cross-validation, Survey-campaign confounding, Data leakage, Feature ablation, Explainable machine learning, Area of applicability, Cattle disease mapping.')

# ------------------------------------------------------------------ 1 introduction
add('h1', '1. Introduction')
para('Contagious bovine pleuropneumonia (CBPP), foot-and-mouth disease (FMD) and lumpy skin disease (LSD) are among the most important cattle diseases in Ethiopia {Gizaw2020, Jemberu2016, Gari2010}. Control programmes need to know where these diseases are reported, but surveillance data are sparse and come from separate projects at different times. Machine-learning models can fill the gaps between surveyed locations, and high accuracy has been reported for livestock disease occurrence {AfshariSafavi2022}, usually with random data splits. When nearby observations are similar, random splits put near-copies of the test data into the training set and accuracy is overstated; spatial block cross-validation reduces this by holding out whole areas {Roberts2017, Ploton2020, Valavi2019}.')
para('Spatial validation does not remove every source of optimism. Rates of disease in nearby locations are useful predictors {Hengl2018}, but they are built from outcome labels and can leak test information {Kaufman2011, Kapoor2023}; a feature that passes a leakage check is safe to use, but this does not show that it is needed. Survey data are also often collected in campaigns that cover different places in different years with different reported prevalence. A model can then score well by recognising the campaign rather than the households at higher risk, a form of dataset shift and sampling bias {MorenoTorres2012, Phillips2009}. Finally, retrospective mapping (where disease was reported during the surveyed period) must be separated from forecasting (where it will be reported later): a model can do the first and fail at the second.')
para('We use a public ILRI dataset of household-reported CBPP, FMD and LSD in Ethiopia {Gizaw2026data}, which a recent preprint analysed with generalised additive mixed models and kriging {Gizaw2026preprint}. We address the machine-learning side with four contributions:')
for t in ['**Spatial generalisation:** random and spatial block cross-validation compared with the same code for four models and three diseases, with train-test distances, the area of applicability, and proximity and block-size sensitivity.',
          '**A leakage-safe framework for outcome-derived neighbourhood features:** rates built from training labels only with the query block excluded, tested by an independent reimplementation, label flipping and permutation controls that rebuild the pipeline, and followed by a feature ablation (FS1 to FS5) and SHAP explanations.',
          '**Survey-campaign confounding:** within-year discrimination, survey-year identification from the features, and models trained on one campaign at a time.',
          '**Retrospective mapping versus temporal generalisation:** a forward test from earlier to later campaigns.']:
    bullet(t)

# ------------------------------------------------------------------ 2 related work
add('h1', '2. Related work')
para('Ignoring spatial structure during cross-validation underestimates prediction error {Roberts2017}; blocks whose size follows the range of spatial autocorrelation are a common remedy {Valavi2019}, and maps of forest biomass with good random-validation scores had little predictive power under spatial validation {Ploton2020}. Other authors argue that map accuracy should be estimated from probability samples and that spatial cross-validation can be pessimistic {Wadoux2021}, propose weighting for clustered samples {deBruin2022}, or match test-to-training distances to prediction distances {Mila2022, Linnenbrink2024}. The area of applicability flags predictions in unfamiliar predictor conditions {Meyer2021}. Because the right block size is not known in advance, we report block-size, proximity and applicability analyses alongside the main spatial blocks.')
para('Studies of CBPP, FMD and LSD in Ethiopia have mostly used questionnaires, outbreak reports and regression models {Gizaw2020, Jemberu2016, Gari2010}, and space-time patterns of LSD outbreaks have been described {Tesfaye2024}. Machine-learning prediction of LSD has reported high accuracy from meteorological and geospatial features with randomly split data {AfshariSafavi2022} and, in Egypt, from animal-level risk factors such as vaccination status with a train-test split of the same outbreaks {Gouda2025}. For FMD in Uganda, machine-learning models that performed well on test data from the same distribution degraded sharply when rainfall and temperature distributions shifted {Kapalaga2024a}, and methods to handle such shifts have been proposed {Kapalaga2024b}. The household surveys used here have been mapped with a year-location factor because survey year and location could not be separated {Gizaw2026preprint}. To our knowledge, no study has evaluated machine-learning models on these data with spatial block validation and an explicit survey-campaign analysis.')
para('Summaries of nearby outcomes are a form of target encoding and must be built from training labels only {Hengl2018, Kaufman2011}; leakage is common across machine-learning studies {Kapoor2023}, and selecting models by noisy cross-validation scores over-fits the selection itself {Cawley2010}. SHAP values {Lundberg2017, Lundberg2020} and partial dependence {Friedman2001} describe what a fitted model uses, but with correlated features such as coordinates and neighbourhood rates they show reliance rather than necessity, so we read them together with an ablation. Pooled surveys can differ between training and test populations in predictors, prevalence or both {MorenoTorres2012, Phillips2009}, and predictive models often transfer poorly to new places and times {Yates2018}.')

# ------------------------------------------------------------------ 3 methods
add('h1', '3. Materials and methods')
add('h2', '3.1 Dataset and preprocessing')
para(f'The data come from household questionnaire surveys by five livestock projects in 2012, 2014, 2015, 2018 and 2019, published by ILRI under a CC BY 4.0 licence {{Gizaw2026data}}. Each household reported whether CBPP, FMD and LSD occurred in its cattle; the outcomes are household-reported occurrence, not laboratory-confirmed infection. The data contain 3,340 households at 462 locations; 449 locations were surveyed in a single year. Overall reported prevalence was {prev["CBPP"]:.1f}% for CBPP, {prev["FMD"]:.1f}% for FMD and {prev["LSD"]:.1f}% for LSD, and it changed strongly between campaigns ({T("data")}, {F("years")}).')
table('data', 'Dataset characteristics and household-reported prevalence by survey year', ['Survey year', 'Households', 'Locations', 'CBPP, n (%)', 'FMD, n (%)', 'LSD, n (%)'], T1.values.tolist(),
      [1400, 1400, 1400, 1800, 1800, 1800], note='Locations add up to more than 462 because 13 locations were surveyed in more than one year.', size=16)
figure('years', FIG / 'Fig2_survey_years_v2.png', '(a) Survey locations coloured by survey year (locations surveyed in several years shown with their most frequent year). (b) Household-reported prevalence by survey year.', width=560)
para(f'The three disease files share household IDs, environmental variables, coordinates and a year-region code; we checked that these were identical and merged them. There were no missing values or duplicate households. Coordinates (0.1 degree precision) were projected to kilometres for blocks and distances. A variable named Weight closely follows the share of same-outcome households at a location (Spearman correlation {WL["spearman_Weight_vs_same_outcome_share"].min():.2f}-{WL["spearman_Weight_vs_same_outcome_share"].max():.2f}) and alone separates cases from non-cases (ROC-AUC {WL.loc["LSD", "discrimination_max(AUC,1-AUC)"]:.2f}-{WL.loc["FMD", "discrimination_max(AUC,1-AUC)"]:.2f}), so it was never used; survey year, region, the year-region code and identifiers were also excluded as predictors.')
add('h2', '3.2 Feature engineering')
para('Five nested feature sets were built (Supplementary Table S24): FS1, five environmental variables (altitude, temperature, precipitation, relative humidity, wind speed); FS2, plus six climate indices (11 features); FS3, plus four coordinate terms (15); FS4, plus 18 neighbourhood and cross-disease rates (33); and FS5, plus six sampling-density terms (39). Rates are computed for all three diseases, so the FMD model also sees nearby CBPP and LSD rates. The difference between consecutive sets estimates what a group adds given the groups before it. For a query location x, the kernel rate for disease d at bandwidth b is given by Eq. (1).')
add('equation', 'r_{b,d}(x) = [ Σ_{j} K_{b}(x, j) · pos_{d}(j) + c · p_{0,d}(x) ] / [ Σ_{j} K_{b}(x, j) · n(j) + c ],   K_{b}(x, j) = exp( −dist(x, j)^{2} / (2b^{2}) )', number=1)
para('Here j runs over training locations outside the 81 km block containing x, n(j) and pos_{d}(j) are the numbers of households and positive households at j, c = 1 is a prior weight, and p_{0,d}(x) is the training rate outside the block of x. Bandwidths were 50, 150 and 400 km; k-nearest-location rates use the 5, 15 and 40 nearest training locations outside the block.')
para('The construction is leakage-safe because it follows three rules: rates are fitted on the training rows of the split only; the whole block of the query location is excluded for training and test rows alike, so no household uses its own or its village\'s label and training features are built under the same conditions as test features; and neighbours are ordered by distance rounded to 10^{-6} km and then by location ID, so exact ties do not depend on row order. The rules were tested in five ways (Section 4.3): an independent reimplementation; flipping all outer-test labels; flipping single training labels; checking that inner folds are block-grouped; and permutation controls that rebuild the pipeline on labels permuted between households or between whole villages. Passing these tests shows that the features do not use test labels, not that they improve prediction; the ablation answers that question.')
add('h2', '3.3 Machine-learning models')
para(f'The feature-set comparison and ablation used ExtraTrees {{Geurts2006}} (300 trees, minimum leaf size 10, square-root feature sampling). The ensemble (a) was the equal-weight average of empirical-distribution ranks of 23 fixed-hyperparameter models (Supplementary Table S25): generalised additive models, random forests {{Breiman2001}}, XGBoost {{Chen2016}}, CatBoost {{Prokhorenkova2018}}, LightGBM {{Ke2017}}, logistic regression, k-nearest neighbours, a multilayer perceptron, a support vector machine and a location-level Gaussian-process model, fitted with scikit-learn {{Pedregosa2011}} and the respective libraries. The comparator (b) is the library model with the best inner out-of-fold ROC-AUC in each split. One library member, a group-balanced CatBoost model, weights training households by the inverse size of their survey year-region group; the code is used as a weight, never as a predictor, and removing this model changed the mean rank-average ROC-AUC by at most {ngb_max:.3f} (Supplementary Table S21). Two corrections were made after the leakage audit (the k-nearest tie rule and the own-block exclusion in a fallback prior); all results use the corrected code except the confirmatory test, which is reported as observed.')
add('h2', '3.4 Spatial validation')
para(f'Households were assigned to 81 km square blocks, and blocks to five folds with balanced household counts ({D1["D1"]["fold_households_range"][0]}-{D1["D1"]["fold_households_range"][1]} test households per fold); three grid origins gave 15 development splits with no location or block in both training and test sets. Five inner block-grouped folds within each training set were used for calibration, thresholds and ensemble ranking. Random household-level 5-fold cross-validation, with the same code, was the reference. The block size was the median practical range of three outcome variograms ({v_out.iloc[0]:.0f}, {v_out.iloc[1]:.0f} and {v_out.iloc[2]:.0f} km) computed earlier on all labels, so the design (though no model) depended on outcomes; label-free variograms had ranges of {v_free.min():.0f} km to beyond 600 km (Supplementary Table S12). We therefore report 120 and 160 km blocks, proximity buffers that remove training locations within 25, 50 or 100 km of any test location, size-matched random removal, the distance from each test household to the nearest training location, and the area of applicability (AOA) of the FS1 and FS5 models {{Meyer2021}} at surveyed locations (the dissimilarity index describes unusual predictor values, not risk).')
para('A confirmatory partition (2 × 5 folds, other grid origins) was sealed before any model was evaluated. It was first reserved for an earlier, pre-registered study of automated feature and model selection by population-based optimisation, which failed its own go/no-go criterion on the development folds and was never tested on it. The partition was then assigned to two hypotheses: H1, FS5 has a higher ROC-AUC than FS1 for both FMD and LSD; H2, FS5 and the rank average differ. They were recorded before opening but after the development results were known, so the test is a held-out check of hypotheses suggested by the development data, not an independent pre-registered confirmation. It was opened once with the code then in use. The optimisation study is outside this paper (Supplementary Section S2).')
add('h2', '3.5 Statistical evaluation')
para('The primary metric was ROC-AUC; we also report PR-AUC with its no-skill level {Saito2015}, the Brier score, calibration intercept and slope {VanCalster2019}, and threshold metrics including the Matthews correlation coefficient {Chicco2020}. Probabilities came from Platt calibration on inner out-of-fold scores and thresholds from the Youden index on the same data. Calibration was assessed within each test fold (fold medians) and on pooled out-of-fold predictions; the Brier skill score compares the Brier score with that of a constant forecast at the prevalence, p(1 - p).')
para('Survey-campaign confounding was measured by the within-year ROC-AUC of Eq. (2), where AUC_{t}, P_{t} and N_{t} are the ROC-AUC and the numbers of positive and negative households in survey year t, so differences in prevalence between campaigns cannot raise the score; by survey-year identification, in which an ExtraTrees classifier predicted each test household\'s survey year from FS1, from the 18 rates alone or from FS5 (macro one-versus-rest ROC-AUC); and by campaign-specific models fitted and tested within one survey year.')
add('equation', 'AUC_{within} = Σ_{t} P_{t} · N_{t} · AUC_{t} / Σ_{t} P_{t} · N_{t}', number=2)
para(f'Paired differences over the 15 folds used the corrected resampled t-test {{Nadeau2003}} with the test-to-training ratio of each design (668/2672 for 81 km blocks; condition-specific for buffers and larger blocks). As a second method, a location-cluster bootstrap (1,000 resamples) was applied to pooled out-of-fold predictions. Holm correction {{Holm1979}} was applied across the three diseases, the 12 ablation steps and the six permutation tests. Negative controls rebuilt the whole pipeline on permuted labels for development repeat 1 ({n_perm:,} household-level and {n_perm:,} village-level permutations; the first 100 per scheme come from the original analysis and 900 were added later with the same code and seed rule); the permutation p-value is (1 + null gains at least as large as the observed gain) / (1 + {n_perm:,}), so it cannot be smaller than {1 / (n_perm + 1):.4f}. Forward temporal validation trained on 2012-2015 (n = 1,564) and tested on 2018-2019 (n = 1,776). Exact SHAP values {{Lundberg2017, Lundberg2020}} of the FS5 model were computed for test households of development repeat 1, partial dependence {{Friedman2001}} on training data, and grouped permutation importance on all folds. Analyses used Python 3.13, scikit-learn 1.9.1, XGBoost 3.4.1, LightGBM 4.7.0, CatBoost 1.2.10 and SHAP 0.54.1 with fixed seeds; an executable notebook reproduces every result ({F("workflow")}).')
figure('workflow', F2D / 'Fig1_workflow_v7.png', 'Study workflow. Steps in blue boxes are repeated inside the training data of each split.', width=520)

# ------------------------------------------------------------------ 4 results
add('h1', '4. Results and discussion')
add('h2', '4.1 Spatial generalisation')
para(f'Random 5-fold cross-validation gave mean fold ROC-AUC of {min(rcv_all):.2f}-{max(rcv_all):.2f} for every model and disease, against {min(fm(d, m) for d in DIS for m in MODELS):.2f}-{max(fm(d, m) for d in DIS for m in MODELS):.2f} under spatial blocks ({T("perf")}; Supplementary Figure S10). For the rank average the difference was {gap_a["CBPP"]:.3f} (CBPP), {gap_a["FMD"]:.3f} (FMD) and {gap_a["LSD"]:.3f} (LSD). Under random splits {same_loc_random:.1f}% of test households had training households at the same location, whereas under 81 km blocks the median distance to the nearest training location was {DST.loc["Spatial 81 km", "Median (km)"]:.0f} km over all test households (Supplementary Table S22). CBPP was the most predictable disease and LSD the least, and the inner-selected single model (b) was never better than the rank average, in line with the selection-bias argument of Cawley and Talbot {{Cawley2010}}. The library also contained a spatial baseline evaluated under the same blocks, a location-level Gaussian-process model on environmental, climate and coordinate inputs (a form of kriging with covariates): its fold-mean ROC-AUC was {gp["CBPP"]:.3f} (CBPP), {gp["FMD"]:.3f} (FMD) and {gp["LSD"]:.3f} (LSD) (Supplementary Table S4), {min(gp_gap):.2f}-{max(gp_gap):.2f} below FS5 and the rank average, so the gain over this simpler spatial model is small.')
rows = []
for _, r in T4.iterrows():
    w = T5[(T5.Disease == r.Disease) & (T5.Model == r.Model)].iloc[0]
    rows.append([r.Disease, r.Model.replace(' Rank average', '').replace(' Inner-selected single', ''), f'{rc(r.Disease, r.Model):.3f}', r['ROC-AUC fold mean (SD)'], r['ROC-AUC pooled [95% CI]'],
                 w['Within-year AUC pooled [95% CI]'], r['PR-AUC (no-skill)'], f"{r['MCC']:.2f}"])
table('perf', 'Discrimination under random and spatial cross-validation (n = 3,340). (a) rank average of 23 models; (b) inner-selected single model.',
      ['Disease', 'Model', 'Random CV ROC-AUC, fold mean', 'Spatial ROC-AUC, fold mean (SD)', 'Spatial ROC-AUC, pooled [95% CI]', 'Spatial within-year AUC, pooled [95% CI]', 'Spatial PR-AUC, fold mean (no-skill)', 'MCC, fold mean'], rows,
      [800, 650, 1100, 1350, 1650, 1700, 1350, 650], size=13,
      note='Spatial: 15 development splits (3 repeats × 5 folds, 81 km blocks). Pooled: out-of-fold predictions of each repeat pooled; 95% CI from 1,000 location-cluster bootstrap resamples. MCC at the Youden threshold from inner out-of-fold data. Further metrics with intervals: Supplementary Tables S1 and S19.')
para(f'Calibration differed between the two views (Supplementary Table S26). Within test folds, median calibration slopes were above 1 for FMD and LSD ({slope_rng("FMD")[0]:.2f}-{slope_rng("FMD")[1]:.2f} and {slope_rng("LSD")[0]:.2f}-{slope_rng("LSD")[1]:.2f}), so probabilities were too close to the average risk; on pooled predictions they were lower ({pool_rng("FMD")[0]:.2f} to {pool_rng("FMD")[1]:.2f} and {pool_rng("LSD")[0]:.2f} to {pool_rng("LSD")[1]:.2f}), which suggests that the overall level of the predictions did not follow differences in prevalence between folds. The Brier skill score was {z2(bss_rng("CBPP")[0])} to {z2(bss_rng("CBPP")[1])} for CBPP, {z2(bss_rng("FMD")[0])} to {z2(bss_rng("FMD")[1])} for FMD and {z2(bss_rng("LSD")[0])} to {z2(bss_rng("LSD")[1])} for LSD, so for FMD and LSD the probabilities should be used for ranking, not as absolute risks.')

add('h2', '4.2 Feature ablation')
r = t7('FS5 minus FS1', 'FMD'); rcb, rl = t7('FS5 minus FS1', 'CBPP'), t7('FS5 minus FS1', 'LSD')
para(f'FS5 improved FMD prediction: the fold-mean gain over FS1 was {ci_flat(r["Overall: fold mean [corrected-t 95% CI]"]).replace(", 95% CI", " (corrected t 95% CI")}; Holm-adjusted p = {r["Overall: Holm p"]:.3f}), better in {r["Overall: folds > 0"]} folds, and the pooled gain was {ci_txt(r["Overall: pooled [bootstrap 95% CI]"]).replace("95% CI", "bootstrap 95% CI")} (Supplementary Table S27). FS5 gave no gain for CBPP ({ci_flat(rcb["Overall: fold mean [corrected-t 95% CI]"])}) and a small, uncertain gain for LSD ({ci_flat(rl["Overall: fold mean [corrected-t 95% CI]"])}). On the held-out confirmatory partition, the FMD gain was {fmd_conf["H1 FS5 - FS1: pooled"]:+.3f} (pooled bootstrap 95% CI {fmd_conf["H1 FS5 - FS1: CI_lo"]:+.3f} to {fmd_conf["H1 FS5 - FS1: CI_hi"]:+.3f}; {fmd_conf["H1 FS5 - FS1: folds better"]} folds; fold-level corrected t-test p = {fmd_conf["H1 FS5 - FS1: p_corrected"]:.3f}) and the LSD gain {S9.loc["LSD", "H1 FS5 - FS1: pooled"]:+.3f} (95% CI {S9.loc["LSD", "H1 FS5 - FS1: CI_lo"]:+.3f} to {S9.loc["LSD", "H1 FS5 - FS1: CI_hi"]:+.3f}). H1, which required both, was not confirmed; the FMD estimate agrees with the development result in direction and size, but its fold-level test was not significant (Supplementary Table S7). For H2, FS5 and the rank average did not differ for FMD ({S9.loc["FMD", "H2 FS5 - (a): pooled"]:+.3f}, 95% CI {S9.loc["FMD", "H2 FS5 - (a): CI_lo"]:+.3f} to {S9.loc["FMD", "H2 FS5 - (a): CI_hi"]:+.3f}), and the rank average was better for LSD ({S9.loc["LSD", "H2 FS5 - (a): pooled"]:+.3f}, 95% CI {S9.loc["LSD", "H2 FS5 - (a): CI_lo"]:+.3f} to {S9.loc["LSD", "H2 FS5 - (a): CI_hi"]:+.3f}).')
pc = lambda s: inc(s, 'FMD', 'Pooled [bootstrap 95% CI]')
pcf = lambda s: pc(s).replace(" [", ", 95% CI ").replace(", +", " to +").replace(", -", " to -").rstrip("]")
para(f'The ablation shows where the FMD gain comes from ({T("abl")}, {F("abl")}). Climate indices added {ci_txt(inc("FS2 - FS1", "FMD"))} and coordinates {ci_txt(inc("FS3 - FS2", "FMD"))} to the fold-mean ROC-AUC; these corrected t-intervals include zero, but the pooled bootstrap intervals excluded it ({pcf("FS2 - FS1")}; {pcf("FS3 - FS2")}). The 18 neighbourhood and cross-disease rates added only {ci_txt(inc("FS4 - FS3", "FMD"))} after the coordinates, and sampling density {ci_txt(inc("FS5 - FS4", "FMD"))}. No single step was significant after Holm correction across the 12 steps. For LSD, adding the rates lowered the within-year ROC-AUC from {float(ab("LSD", "FS3", "Within-year AUC fold mean")):.3f} to {float(ab("LSD", "FS4", "Within-year AUC fold mean")):.3f}, which suggests that for LSD the rates carry between-campaign information (Section 4.6). The engineered set therefore improves FMD; the ablation shows that the gain comes mainly from climate indices and coordinates, while neighbourhood and cross-disease rates add little once location is known and partly encode the survey campaign. The leakage audit shows that these rates are safe, not that they are needed. Because the rates were added after the coordinates and both describe location, the ablation measures what the rates add beyond coordinates, not what they could provide alone.')
rows = []
for s, g in zip(['FS1', 'FS2', 'FS3', 'FS4', 'FS5'], ['Environmental (5)', '+ Climate indices (11)', '+ Coordinates (15)', '+ Neighbourhood and cross-disease rates (33)', '+ Sampling density (39)']):
    row = [s, g]
    for d in DIS:
        row.append(ab(d, s, 'ROC-AUC pooled [95% CI]'))
        row.append('-' if s == 'FS1' else inc({'FS2': 'FS2 - FS1', 'FS3': 'FS3 - FS2', 'FS4': 'FS4 - FS3', 'FS5': 'FS5 - FS4'}[s], d))
    rows.append(row)
